Assume that $\alpha\to\infty$, with $\ell$ fixed and $M=O(\alpha^{\sfrac12}/(\log\alpha)^2)$.
		\begin{enumerate}[(i)]
			\item Consider an FMIS $S$ of $G$. Define 
			\begin{align}
				\mathscr{P}(S)&:=\exp(P|F|+\tfrac12P|R^*(S)|+P{\bf{w}}(V)-{\bf{w}}(S))\prod_{t=1}^{\alpha}\frac{t}{n_t},\\
				\mathscr{E}(\alpha,M)&:=\frac{M^2\log\alpha}{\alpha}+\frac{M(\log\alpha)^2}{\alpha}.
			\end{align}
			Then the IMFIS process samples $S$ with probability
			\begin{align}
				\mathbb{P}(\boldsymbol{S}_{\infty}=S)&=(1+O(\mathscr{E}(\alpha,M)))\mathscr{P}(S).
			\end{align}
			\item The IMFIS process samples an FMIS with probability $$\mathbb{P}(|\boldsymbol{S}_{\infty}|=\alpha)=1-O(M/\alpha).$$ In particular, for $\alpha$ sufficiently large, this probability is positive, so $G$ has at least one FMIS.
		\end{enumerate}

Let $0<\delta<1$ with $\delta=O(\tfrac{\log\log\alpha}{\log\alpha})$, such that there exist $\mu_1,\mu_2>0$ with $\mu_2=\Omega(1)$, $\mu_1+\mu_2=1$, and
		\begin{align}
			\delta&\geq\tfrac1{\mu_1}\left(8\left(1-\tfrac{\log M}{\log\alpha}\right)+2+\Omega(1)\right)\tfrac{\log\log\alpha}{\log\alpha},
			\\\delta\left(1-\tfrac{\log M}{\log\alpha}\right)&\leq4\left(\tfrac12-\tfrac{\log M}{\log\alpha}\right)-(\tfrac{1}{\mu_2}+\Omega(1))\tfrac{\log\log\alpha}{\log\alpha}.
		\end{align}
		Then we have $$\mathbb{E}(\Pi1_{\mathcal{P}\setminus\mathcal{P}^{\delta}})\leq\tfrac{M}{\alpha}\exp\left(O\left(\tfrac{k\log\alpha}{\log\log\alpha}\right)\right).$$

define the event $$\mathcal{Q}_t^{\delta}:=\{n_{\alpha-r}-\Psi_r<\delta(n_{\alpha-r}-K)\ \text{for}\ r:=\alpha-k-t\},$$ such that $\mathcal{P}_{t+1}^{\delta}\setminus\mathcal{P}_t^{\delta}=\mathcal{P}_{t+1}^{\delta}\cap\mathcal{Q}_t^{\delta}$.

	\begin{lemma}                                                                                                                                   \end{lemma}

	\begin{proof}                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      \end{proof}

	We can now prove Lemma~6.10.

